CREATE EXTENSION IF NOT EXISTS btree_gist;
CREATE TABLE ads_campaigns(id uuid PRIMARY KEY,owner_id text NOT NULL,brief jsonb NOT NULL,current_revision uuid,state text NOT NULL DEFAULT 'DRAFT',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ads_uploads(id uuid PRIMARY KEY,owner_id text NOT NULL,storage_key text NOT NULL,hash text NOT NULL,mime text NOT NULL,width integer NOT NULL CHECK(width>0),height integer NOT NULL CHECK(height>0),size integer NOT NULL CHECK(size>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ads_revisions(id uuid PRIMARY KEY,campaign_id uuid NOT NULL REFERENCES ads_campaigns(id),brief jsonb NOT NULL,logo_id uuid NOT NULL REFERENCES ads_uploads(id),content_hash text NOT NULL,state text NOT NULL DEFAULT 'DRAFT',verdict jsonb,manifest jsonb,manifest_hash text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ads_quotes(id uuid PRIMARY KEY,owner_id text NOT NULL,campaign_id uuid NOT NULL REFERENCES ads_campaigns(id),revision_id uuid NOT NULL REFERENCES ads_revisions(id),snapshot jsonb NOT NULL,terms_hash text NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ads_orders(id uuid PRIMARY KEY,owner_id text NOT NULL,quote_id uuid NOT NULL UNIQUE REFERENCES ads_quotes(id),revision_id uuid NOT NULL REFERENCES ads_revisions(id),state text NOT NULL DEFAULT 'RESERVED',queue_state text,amount numeric(39,0) NOT NULL CHECK(amount>0),pay_to text NOT NULL,payer text,terms_hash text NOT NULL,quote jsonb NOT NULL,reason text,suspended boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ads_inventory(id text PRIMARY KEY CHECK(id IN ('venue_center_banner','main_stage_screen')),playlist_version bigint NOT NULL DEFAULT 0);
INSERT INTO ads_inventory(id) VALUES('venue_center_banner'),('main_stage_screen');
CREATE TABLE ads_reservations(
 id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES ads_orders(id),placement_id text NOT NULL REFERENCES ads_inventory(id),
 starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,expires_at timestamptz NOT NULL,state text NOT NULL CHECK(state IN ('HELD','COMMITTED','RELEASED')),
 pass_id uuid,CHECK(ends_at>starts_at),
 EXCLUDE USING gist(placement_id WITH =,tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE(state IN ('HELD','COMMITTED'))
);
CREATE INDEX ads_reservation_order ON ads_reservations(order_id);
CREATE TABLE ads_placements(order_id uuid NOT NULL REFERENCES ads_orders(id),placement_id text NOT NULL REFERENCES ads_inventory(id),required_units bigint NOT NULL CHECK(required_units>0),delivered_units bigint NOT NULL DEFAULT 0 CHECK(delivered_units>=0),unit text NOT NULL,state text NOT NULL DEFAULT 'PENDING',PRIMARY KEY(order_id,placement_id),CHECK(delivered_units<=required_units));
CREATE TABLE ads_outbox(id uuid PRIMARY KEY,topic text NOT NULL,aggregate_id uuid NOT NULL,payload jsonb NOT NULL DEFAULT '{}',dedupe_key text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'READY',attempts integer NOT NULL DEFAULT 0,available_at timestamptz NOT NULL DEFAULT now(),lease_until timestamptz,lease_owner text,lease_version bigint NOT NULL DEFAULT 0,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ads_outbox_ready ON ads_outbox(status,available_at);
CREATE TABLE ads_events(id bigserial PRIMARY KEY,aggregate_id uuid,actor text NOT NULL,event text NOT NULL,data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ads_idempotency(owner_id text NOT NULL,key text NOT NULL,action text NOT NULL,fingerprint text NOT NULL,response jsonb,created_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(owner_id,key));
CREATE TABLE ads_leases(name text PRIMARY KEY,owner text NOT NULL,fence bigint NOT NULL DEFAULT 1,expires_at timestamptz NOT NULL);
CREATE TABLE ads_playlist(placement_id text PRIMARY KEY REFERENCES ads_inventory(id),version bigint NOT NULL,order_id uuid REFERENCES ads_orders(id),revision_id uuid REFERENCES ads_revisions(id),reservation_id uuid REFERENCES ads_reservations(id),manifest_hash text,active jsonb,valid_until timestamptz NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ads_delivery(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES ads_orders(id),placement_id text NOT NULL REFERENCES ads_inventory(id),revision_id uuid NOT NULL,manifest_hash text NOT NULL,playlist_version bigint NOT NULL,fence bigint NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,units bigint NOT NULL CHECK(units>0),pass_id uuid UNIQUE,signature text NOT NULL,publisher_key text NOT NULL,evidence jsonb NOT NULL,CHECK(ends_at>starts_at),EXCLUDE USING gist(placement_id WITH =,tstzrange(starts_at,ends_at,'[)') WITH &&));
CREATE TABLE ads_publisher_acks(placement_id text PRIMARY KEY,order_id uuid NOT NULL,revision_id uuid NOT NULL,manifest_hash text NOT NULL,image_hash text NOT NULL,version bigint NOT NULL,fence bigint NOT NULL,ack_at timestamptz NOT NULL,pass_id uuid,pass_started_at timestamptz);
CREATE TABLE ads_disputes(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES ads_orders(id),owner_id text NOT NULL,reason text NOT NULL,state text NOT NULL DEFAULT 'OPEN',created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE ads_consents(id uuid PRIMARY KEY,order_id uuid NOT NULL REFERENCES ads_orders(id),owner_id text NOT NULL,proposal jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ads_rate_limits(key text PRIMARY KEY,count integer NOT NULL DEFAULT 1,expires_at timestamptz NOT NULL);
